const unparentRestoredOrphans = `-- name: UnparentRestoredOrphans :many
UPDATE tasks c
SET parent_task_id = NULL,
    revision = c.revision + 1,
    updated_at = now()
WHERE c.organization_id = $1
  AND c.workspace_id = $2
  AND c.trash_batch_id = $3
  AND c.parent_task_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM tasks p
    WHERE p.id = c.parent_task_id
      AND p.organization_id = c.organization_id
      AND p.workspace_id = c.workspace_id
      AND (p.trashed_at IS NULL OR p.trash_batch_id = c.trash_batch_id)
  )
RETURNING c.id
`

type UnparentRestoredOrphansParams struct {
	OrganizationID string      `json:"organization_id"`
	WorkspaceID    string      `json:"workspace_id"`
	TrashBatchID   pgtype.Text `json:"trash_batch_id"`
}

// Run BEFORE RestoreTaskBatch, while the rows still carry the batch. A member
// whose parent is not coming back with it (parent still trashed in another
// batch, or already purged) becomes a root, so it never points at a row the
// reader cannot see.
func (q *Queries) UnparentRestoredOrphans(ctx context.Context, arg UnparentRestoredOrphansParams) ([]string, error) {
	rows, err := q.db.Query(ctx, unparentRestoredOrphans, arg.OrganizationID, arg.WorkspaceID, arg.TrashBatchID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
